            st, g = await h.jget(f"{API}/refs", root=key)
            pick0 = rows(g)[ids[1]]["pick"]
            auto0 = refs.resolve_refs(str(rd), {"id": ids[1], "name": "002_장갑_왼쪽"}, doc(root))["refs_auto"]
