        check(pl.update(root, 4, "import", der["settings"]["import"])["rev"] == 5, "import 되돌림 저장 rev 5")
        r5c = pl.update(root, 5, "cand", dict(der["settings"]["cand"], enabled=True, path="C:/없는/h.psd"))
