    off = re.search(r"const MASK_OFF = new Set\(\[\.\.\.EDIT_OFF, ([^\]]*)\]\)", bj)
    check(bool(off) and set(re.findall(r'"(\w+)"', off.group(1))) == {"KeyE", "KeyT", "KeyG"}, "MASK_OFF = 검토 키 + E·T·G")
    kd = _layout_js_fn(bj, "onKeyDown")
